const fs = require("fs");
const path = require("path");

const root = process.argv[2];
const PILL_TAGS = new Set(["app-pill", "app-fancy-pill", "app-status-pill"]);
const SKIP = new Set(["node_modules", ".git", "dist", ".angular"]);

function walk(dir, out) {
    for (const e of fs.readdirSync(dir, { withFileTypes: true })) {
        if (SKIP.has(e.name)) continue;
        const p = path.join(dir, e.name);
        if (e.isDirectory()) walk(p, out);
        else if (/\.(ts|html)$/.test(e.name)) out.push(p);
    }
    return out;
}

function processTags(src) {
    const re = /<(app-[a-z-]+)(?=[\s/>])/g;
    let out = "";
    let last = 0;
    let m;
    let count = 0;
    while ((m = re.exec(src))) {
        const name = m[1];
        const start = m.index;
        let j = start + m[0].length;
        let quote = null;
        while (j < src.length) {
            const c = src[j];
            if (quote) { if (c === quote) quote = null; }
            else if (c === '"' || c === "'") quote = c;
            else if (c === ">") break;
            j++;
        }
        if (PILL_TAGS.has(name)) {
            const tag = src.slice(start, j + 1);
            const newTag = tag
                .replace(/\[disableTooltip\]/g, "[hideHint]")
                .replace(/(\s)disableTooltip(?=[\s/>])/g, "$1hideHint");
            if (newTag !== tag) {
                out += src.slice(last, start) + newTag;
                last = j + 1;
                count++;
            }
        }
        re.lastIndex = j + 1;
    }
    out += src.slice(last);
    return { text: out, count };
}

function processReads(src) {
    // Rename every ".disableTooltip()" read except receivers that are app-card refs.
    const re = /(?<!summary|\bcard\(\)\?|\bcard)\.disableTooltip\(\)/g;
    let count = 0;
    const text = src.replace(re, () => { count++; return ".hideHint()"; });
    return { text, count };
}

const files = walk(root, []);
let totalTags = 0, totalReads = 0;
for (const f of files) {
    const orig = fs.readFileSync(f, "utf8");
    const a = processTags(orig);
    const b = processReads(a.text);
    if (b.text !== orig) {
        fs.writeFileSync(f, b.text, "utf8");
        console.log(`${path.relative(root, f)}: tags=${a.count} reads=${b.count}`);
    }
    totalTags += a.count;
    totalReads += b.count;
}
console.log(`TOTAL tags=${totalTags} reads=${totalReads} files=${files.length}`);

